SELECT CONTENT_TYPE_ID
FROM CONTENTTYPES
WHERE CONTENT_TYPE_NAME = #{content}

	SELECT a.*
	FROM attractions a
	WHERE a.area_code = (
       	SELECT sido_code
        FROM guguns
        WHERE no = #{no}
    )
  	AND a.si_gun_gu_code = (
        SELECT gugun_code
        FROM guguns
        WHERE no = #{no}
    	)
	ORDER BY a.likes DESC
    limit #{offset}, 8;

  	SELECT a.*
	FROM attractions a
	JOIN SIDOS s ON a.area_code = s.sido_code
	WHERE s.sido_name = #{sido}
	ORDER BY a.likes DESC 	
    limit #{offset}, 8;

SELECT EXISTS(
    SELECT 1
    FROM likes
    WHERE uid = #{uid} AND ano = #{ano}
	)

mapper.update:
    	UPDATE ATTRACTIONS
		SET likes = likes - 1
		WHERE no = #{ano};

    	UPDATE ATTRACTIONS
		SET likes = likes + 1
		WHERE no = #{ano};

